.ds-preview { color: #2b211a; font-family: "Helvetica Neue", Helvetica, "Archivo", Arial,
    sans-serif; } .ds-btn-outline { min-height: 64px; display: inline-flex; align-items: center; padding: 0 clamp(22px, 2.6vw, 32px); border: 2px solid #2b211a; background: none; color: #2b211a; font-family: inherit; font-size: clamp(24px, 2.7vw, 32px); line-height: 1.2; letter-spacing: 0.05em; text-transform: uppercase; text-decoration: none; cursor: pointer; transition: background-color 160ms cubic-bezier(0.22, 1, 0.36, 1),
